const analysis=e=>({geometry:medianGeometry(e.width,e.height),probabilities:Float32Array.from(e.probabilities),variances:Float64Array.from(e.variances),margins:new Float32Array(e.probabilities.length)}),sha=a=>createHash('sha256').update(a).digest('hex');
async function clock(fn,{advance=0,onYield}={}){const d=Object.getOwnPropertyDescriptor(performance,'now'),timer=globalThis.setTimeout;let now=0,yields=0;Object.defineProperty(performance,'now',{configurable:true,value:()=>now+=advance});globalThis.setTimeout=(f,ms,...a)=>{if(ms===0){yields++;onYield?.();}return timer(f,ms,...a);};try{return{value:await fn(),yields};}finally{if(d)Object.defineProperty(performance,'now',d);else delete performance.now;globalThis.setTimeout=timer;}}
test('240 native renders preserve bytes, masks, float32 grids, thresholds and historical padding',async()=>{let n=0;for(const e of cases)for(const r of e.renders){const a=await medianRender(analysis(e),r.params);assert.equal(sha(a.pixels.data),r.rgbSha256);assert.deepEqual([...a.filtered],r.filtered);assert.deepEqual([...a.valid],r.valid);assert.deepEqual([...a.decisions],r.decisions);assert.equal(a.validBlocks,r.validBlocks);assert.ok(Math.abs(a.mean-r.mean)<=1e-14);n++;}assert.equal(n,240);});
test('small cached render does not wait for forced timers',async()=>{const result=await clock(()=>medianRender(analysis(cases[2])));assert.equal(result.yields,0);});
test('one deadline spans small separately rendered row bands',async()=>{const a=analysis(cases[2]),grid=await medianGrid(a);const result=await clock(async()=>{const cooperate=createCooperator();for(let y=0;y<67;y++)await medianEnlargeRows(grid.rgb,a.geometry,{start:y,rows:1,cooperate});},{advance:1});assert.ok(result.yields>=6);});
test('row band boundaries preserve exact absolute interpolation coordinates',async()=>{for(const e of cases){const a=analysis(e),p=e.renders[17].params,grid=await medianGrid(a,p),bytes=new Uint8Array(e.width*e.height*3);for(let y=0;y<e.height;y+=7)bytes.set(await medianEnlargeRows(grid.rgb,a.geometry,{start:y,rows:Math.min(7,e.height-y)}),y*e.width*3);assert.equal(sha(bytes),e.renders[17].rgbSha256);}});
for(const phase of['grid','rows','render'])test('cooperative cancellation rejects '+phase,async()=>{const controller=new AbortController(),a=analysis(cases[2]),grid=await medianGrid(a);await assert.rejects(clock(()=>phase==='grid'?medianGrid(a,{}, {signal:controller.signal}):phase==='rows'?medianEnlargeRows(grid.rgb,a.geometry,{signal:controller.signal}):medianRender(a,{}, {signal:controller.signal}),{advance:9,onYield:()=>controller.abort()}),{code:'CANCELLED'});});
test('signal passed to source reads; final abort releases the actual window',async()=>{const controller=new AbortController(),g=medianGeometry(65,67);let reads=0,releases=0;const read=medianSurfaceReader({async readWindow(rect,hooks){assert.equal(hooks.signal,controller.signal);reads++;controller.abort();return{pixels:{...rect,format:'rgb8',data:new Uint8Array(rect.width*rect.height*3)},release(){releases++;}};}});await assert.rejects(read(0,1,g,{signal:controller.signal}),{code:'CANCELLED'});assert.equal(reads,1);assert.equal(releases,1);});
async function dispose(r){await r.surface.dispose();for(const m of Object.values(r.maskRecords))await m.surface.dispose();}
function setup(limit=64*1024**2){const budget=new Budget(limit),e=cases[2],a=analysis(e),image={surface:{descriptor:{width:e.width,height:e.height}}},model={metadata:{features:8},predict(){throw Error("Unexpected model path");}},pool={profile:{maxWorkers:2},async run(image,model,hooks){hooks.onProgress?.(1);return{...analysis(e),runtime:{}};}};return{budget,image,model,medianPool:pool,e,a};}
test('segmented retained cache is defensive and independent masks survive RGB disposal',async()=>{const s=setup(),r=await segmentedMedian(s.image,{}, {...s,cacheKey:'source-model',dependencies:['source','model'],rowsPerBlock:1});assert.equal(r.metrics.analysisCacheHit,false);r.data.probabilities.fill(1);const next=await segmentedMedian(s.image,{}, {...s,cacheKey:'source-model',rowsPerBlock:3});assert.equal(next.metrics.analysisCacheHit,true);assert.deepEqual([...next.data.probabilities],s.e.probabilities);await r.surface.dispose();const m=await r.maskRecords.valid.surface.readWindow();m.release();for(const x of Object.values(r.maskRecords))await x.surface.dispose();await dispose(next);s.budget.clearDependencies('model');assert.equal(s.budget.total(),0);});
for(const at of[.8,.9,1])test('segmented callback cancellation '+at+' rolls back all unpublished owners',async()=>{const s=setup(),controller=new AbortController();await assert.rejects(segmentedMedian(s.image,{}, {...s,rowsPerBlock:3,signal:controller.signal,onProgress:f=>{if(f>=at)controller.abort();}}),{code:'CANCELLED'});assert.equal(s.budget.total(),0);});
test('low budget refuses before feature work or publication',async()=>{const s=setup(1024);s.medianPool.run=()=>assert.fail('Features before admission');await assert.rejects(segmentedMedian(s.image,{},s),{code:'MEMORY_LIMIT'});assert.equal(s.budget.total(),0);});
test('all EXIF orientations and native block row crossings keep the original padding bytes',async()=>{const{createSegmentedBytes}=await import('../src/segmented-bytes.js'),{createRgbSurface}=await import('../src/rgb-surface.js'),{orientRgb}=await import('../src/image-headers.js'),{medianGrayBlock}=await import('../src/median.js');const pixels={width:129,height:64,format:'rgb8',data:Uint8Array.from({length:129*64*3},(_,i)=>i*37^(i>>>7))};for(let orientation=1;orientation<=8;orientation++){const budget=new Budget(32*1024**2),store=await createSegmentedBytes(pixels.data.length,{budget,chunkBytes:113});await store.write(pixels.data);const surface=createRgbSurface(store,{...pixels,budget,orientation});try{const expected=await orientRgb(pixels,orientation),g=medianGeometry(expected.width,expected.height),read=medianSurfaceReader(surface),count=g.blockColumns*g.blockRows;for(let start=0;start<count;start+=2){const length=Math.min(2,count-start),actual=await read(start,length,g);for(let j=0;j<length;j++)assert.deepEqual(actual.subarray(j*4096,(j+1)*4096),medianGrayBlock(expected,start+j,g));}}finally{await surface.dispose();}assert.equal(budget.total(),0);}});
test('parameter and finite-grid validation remain strict',async()=>{const{medianParams}=await import('../src/median.js');for(const p of[{variance:1.5},{variance:-1},{variance:101},{threshold:-.01},{threshold:1.01},{threshold:NaN},{threshold:Infinity},{surprise:1},{speckle:'false'}])assert.throws(()=>medianParams(p),{code:'INVALID_INPUT'});for(const invalid of[-1,1.1,NaN,Infinity]){const a=analysis(cases[2]);a.probabilities[0]=invalid;await assert.rejects(medianGrid(a),{code:'INVALID_INPUT'});}});
